-- 41 Waterfall Grotto: flickers the torch lights and puts them out and
-- back. The falling water, the ripples, the torch flames, the crystals and
-- the moss are the engine's animated tiles (`animations` on the tileset).
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/41-waterfall-grotto.scene"
local post_on = nav.post_all_on(SCENE)
local captions = true
local torches, glows = {}, {}
local lit = true
local t = 0

function init(entity)
    for i = 1, 3 do
        torches[i] = Entity.find_by_name("Torch" .. i)
        glows[i] = Entity.find_by_name("TorchGlow" .. i)
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then lit = not lit end
    t = t + dt
    for i, e in ipairs(torches) do
        if e then
            local f = 1.7 + 0.18 * math.sin(t * 11 + i * 2) + 0.1 * math.sin(t * 23 + i)
            Lighting.set_intensity(e, lit and f or 0)
        end
        if glows[i] then Sprite.set_color(glows[i], 1.0, 0.31, 0.05, lit and 0.45 or 0) end
    end
end
